#!/usr/bin/env python3
"""Generate French translations for the 7 long articles (indices 12-18)."""
import json

missing = json.load(open('fr_missing_long.json'))

translations = {}

# Index 12: Fire triangle article
translations[missing[12]] = """<p>Le <strong>triangle du feu</strong> est le principe fondamental de la science du feu. Le feu nécessite trois éléments, et en retirer un seul éteint le feu :</p><p><strong>Air (Oxygène) :</strong> Le feu a besoin d'oxygène pour brûler. C'est pourquoi vous construisez des foyers avec des espaces pour le circulation d'air. Étouffer un feu le prive d'oxygène — c'est ainsi qu'une couverture anti-feu ou du sable éteint les flammes. Trop de vent peut aussi éteindre un petit feu avant qu'il ne s'établisse.</p><p><strong>Chaleur :</strong> La chaleur est l'énergie qui maintient la réaction chimique de combustion. Votre étincelle de silex et d'acier fournit la chaleur initiale. Une fois enflammé, le feu génère sa propre chaleur. Retirez la chaleur (avec de l'eau, qui refroidit) et le feu meurt.</p><p><strong>Combustible :</strong> Le combustible est ce qui brûle. En situation de survie, il s'agit de bois de tailles progressivement plus grandes. Retirez le combustible et le feu s'éteint — c'est pourquoi vous dégagez la zone autour de votre cercle de feu de tout matériau combustible.</p><p>Comprendre le triangle vous aide à la fois à construire des feux (fournir les trois éléments) et à les éteindre (en retirer un ou plusieurs). L'eau retire la chaleur et l'oxygène. Remuer expose tous les points chauds. La terre étouffe l'oxygène. Un foyer correctement construit assure une circulation d'air adéquate vers tout le combustible.</p>"""

# Index 13: Rule of three article
translations[missing[13]] = """<p>La <strong>règle de trois</strong> est un moyen mnémotechnique simple qui établit les priorités de survie selon la durée pendant laquelle vous pouvez survivre sans chaque besoin :</p><p><strong>3 minutes sans air :</strong> L'oxygène est le besoin le plus immédiat. En cas de noyade, d'étouffement ou de voies respiratoires bloquées, vous disposez d'environ 3 minutes.</p><p><strong>3 heures sans abri :</strong> Dans des conditions extrêmes (froid glacial, chaleur intense, tempête), vous pouvez survivre environ 3 heures sans abri adéquat. Cela fait de l'abri votre priorité physique la plus élevée après l'air.</p><p><strong>3 jours sans eau :</strong> La déshydratation devient critique après 3 jours. La recherche et la purification de l'eau doivent intervenir tôt dans votre chronologie de survie.</p><p><strong>3 semaines sans nourriture :</strong> Vous pouvez survivre environ 3 semaines sans nourriture. Cela fait de la nourriture la priorité de survie la plus basse — vous avez le temps de vous en occuper après avoir sécurisé l'abri, l'eau et le feu.</p><p>Cette règle détermine directement les cinq éléments de priorité de survie : Attitude, Abri, Eau, Feu, Nourriture. Votre attitude mentale soutient tout, l'abri répond à la limite de 3 heures, l'eau à la limite de 3 jours, et la nourriture à la limite de 3 semaines.</p>"""

# Index 14: Seven enemies of survival article
translations[missing[14]] = """<p>Les <strong>sept ennemis de la survie</strong> sont les forces physiques et psychologiques qui érodent votre capacité à survivre. Chacun doit être reconnu et activement combattu :</p><p><strong>Douleur :</strong> Les blessures causent une douleur qui peut submerger votre jugement. Traitez les blessures avec des premiers secours, immobilisez les entorses et gérez la douleur afin de pouvoir penser clairement et agir efficacement.</p><p><strong>Froid :</strong> L'hypothermie est le tueur numéro un en pleine nature. Combattez le froid avec un abri, du feu, des vêtements secs et une isolation du sol. Ne vous laissez jamais rester mouillé et exposé.</p><p><strong>Soif :</strong> Vous ne pouvez survivre que 3 jours sans eau. Localisez et purifiez l'eau tôt. Rationnez la transpiration, pas l'eau — buvez quand vous en avez.</p><p><strong>Faim :</strong> Vous pouvez survivre 3 semaines sans nourriture, c'est donc la priorité la plus basse. Mais la faim sappe l'énergie et le moral. Ne cueillez en sécurité que lorsque vous pouvez identifier les plantes avec 100 % de certitude.</p><p><strong>Fatigue :</strong> L'épuisement conduit à des erreurs et des blessures. Planifiez du repos, rythmez vos activités et dormez quand c'est sûr. Un survivant reposé prend de meilleures décisions.</p><p><strong>Ennui :</strong> Le temps mort en survie peut être psychologiquement dévastateur. Restez occupé avec des améliorations du camp, l'entretien du feu, la préparation des signaux et des tâches de routine.</p><p><strong>Solitude :</strong> L'isolement érode la volonté de vivre. Maintenez l'espoir, parlez à vous-même, tenez un journal et fixez des objectifs quotidiens. Votre attitude mentale est l'outil de survie le plus important que vous possédez.</p>"""

# Index 15: Universal distress signal article
translations[missing[15]] = """<p>Le <strong>signal de détresse universel</strong> est <strong>trois de n'importe quoi</strong>. Ce modèle est internationalement reconnu :</p><p><strong>Trois coups de sifflet :</strong> Soufflez trois coups brefs sur votre sifflet de survie, faites une pause, puis répétez. Un sifflet porte beaucoup plus loin qu'une voix et utilise moins d'énergie.</p><p><strong>Trois éclairs de miroir :</strong> Flasher un miroir de signal trois fois vers les aéronefs ou les observateurs distants. L'éclair du miroir peut être vu à de nombreux kilomètres par temps ensoleillé.</p><p><strong>Trois feux :</strong> Trois feux disposés en <strong>triangle</strong>, espacés de <strong>35 mètres</strong>, constituent un signal de détresse aérien internationalement reconnu. Il se distingue clairement d'un seul feu de camp ou d'un feu naturel.</p><p><strong>Trois coups de feu :</strong> Si vous avez une arme à feu, trois tirs successifs signalent la détresse. (À utiliser uniquement si c'est sûr et légal.)</p><p><strong>Trois colonnes de fumée :</strong> Trois feux fumés distincts (ajoutez des branches vertes pour produire de la fumée blanche) sont visibles depuis les airs pendant la journée.</p><p><strong>Symboles de signal sol-air :</strong> Marquez des symboles sur le sol dégagé avec des roches, des rondins ou des tranchées. Chaque symbole doit mesurer <strong>1 mètre de large et 8 mètres de long</strong>, avec les symboles espacés de <strong>3 mètres</strong>. Symboles clés : <strong>V</strong> (assistance requise), <strong>X</strong> (assistance médicale requise), <strong>F</strong> (besoin de nourriture et d'eau), <strong>flèche</strong> (progrédant dans cette direction).</p>"""

# Index 16: Psychology of survival (REACT) article
translations[missing[16]] = """<p>L'outil de survie le plus critique n'est pas un couteau, un feu ou un abri — c'est <strong>votre esprit</strong>. La survie est à 90 % psychologique. Les cadets qui survivent sont ceux qui maintiennent une attitude positive et déterminée.</p><p><strong>La panique est le premier ennemi.</strong> Lorsqu'une catastrophe frappe, la réponse naturelle est la panique. La panique provoque des décisions irrationnelles, une course sans but et un gaspillage d'énergie. La procédure S.T.O.P. existe précisément pour combattre la panique — s'asseoir vous force à vous arrêter, respirer et réfléchir.</p><p><strong>L'acronyme REACT</strong> aide à gérer le stress psychologique :</p><p><strong>R</strong> — Reconnaître la situation. Ne niez pas la réalité. Acceptez que vous êtes dans une situation de survie.</p><p><strong>E</strong> — S'attendre à survivre. Croyez que vous y arriverez. Cette croyance guide toutes vos actions.</p><p><strong>A</strong> — Évaluer vos ressources. Qu'avez-vous ? Que pouvez-vous utiliser ? Quelles sont vos priorités ?</p><p><strong>C</strong> — Créer un plan. Utilisez S.T.O.P. Prenez des décisions basées sur votre évaluation et la règle de trois.</p><p><strong>T</strong> — Passer à l'action. Exécutez votre plan. Rester occupé combat l'ennui et vous donne un but.</p><p><strong>Combattre les ennemis psychologiques :</strong> L'ennui et la solitude peuvent détruire votre volonté de survivre. Combattez-les en fixant des objectifs quotidiens, en maintenant des routines, en gardant votre camp organisé, en entretenant votre feu et en gardant l'espoir vivant. Parlez à vous-même, chantez ou tenez un journal. Votre esprit est votre meilleur ami ou votre pire ennemi en survie — choisissez d'en faire votre allié.</p>"""

# Index 17: Finding water article
translations[missing[17]] = """<p>L'eau est votre troisième priorité de survie. Voici des méthodes pour localiser l'eau dans la nature :</p><p><strong>Signes d'animaux :</strong> Les sentiers d'animaux mènent souvent à l'eau. Suivez-les en descendant, surtout si plusieurs sentiers convergent. Les animaux brouteurs boivent généralement à l'aube et au crépuscule.</p><p><strong>Habitudes de vol des oiseaux :</strong> Les oiseaux, surtout les oiseaux aquatiques, volent souvent vers l'eau à l'aube et s'en éloignent au crépuscule. Suivez leur direction de vol à ces moments.</p><p><strong>Végétation :</strong> Une végétation luxuriante et verte dans une zone par ailleurs sèche indique de l'eau à proximité. Les saules, les peupliers et les quenouilles poussent près de l'eau. Creusez près de leurs racines dans les lits de ruisseaux asséchés — l'eau peut être juste sous la surface.</p><p><strong>Drainage naturel :</strong> Suivez les ravins, les rigoles et les fonds de vallée en descendant. L'eau coule vers le point le plus bas. Les lits de ruisseaux asséchés peuvent avoir de l'eau sous la surface — creusez dans le virage extérieur le plus bas.</p><p><strong>Collecte de rosée :</strong> En l'absence d'eau courante, collectez la rosée du matin en essuyant l'herbe et les feuilles avec un chiffon propre, puis en l'essorant dans un récipient. Cela peut fournir une quantité importante d'eau dans les zones riches en rosée.</p><p><strong>Neige et glace :</strong> Fondez la neige ou la glace pour obtenir de l'eau. Préférez la glace à la neige — elle donne plus d'eau par volume. Fondez toujours avant de boire pour éviter de baisser votre température corporelle.</p><p><strong>Attention :</strong> Évitez l'eau de couleur, d'odeur ou de mousse inhabituelles. Évitez l'eau en aval des mines, des colonies ou des zones agricoles. Et purifiez toujours avant de boire.</p>"""

# Index 18: Feather sticks article
translations[missing[18]] = """<p>Lorsque le bois est humide à cause de la pluie, de la neige ou d'une forte humidité, trouver de l'amadou et du petit bois secs est un défi. Les <strong>bâtons à plumes</strong> sont la solution.</p><p><strong>Qu'est-ce qu'un bâton à plumes ?</strong> Un bâton à plumes est un morceau de bois fendu avec de fines copeaux (plumes) laissés attachés au bâton. Les copeaux fins s'enflamment facilement, et le bois sec intérieur du bâton maintient la flamme.</p><p><strong>Comment faire des bâtons à plumes :</strong></p><p>1. Trouvez une branche morte sèche encore debout (toujours attachée à l'arbre, pas sur le sol où elle absorbe l'humidité). Le bois mort debout est plus sec que le bois tombé.</p><p>2. Fendez la branche ouverte avec votre couteau ou votre hache. Le bois intérieur est protégé de l'humidité et devrait être sec même lorsque l'extérieur est mouillé.</p><p>3. Tenez le bâton fendu fermement. Avec votre couteau, faites des coups de copeaux vers le bas, en laissant chaque copeau attaché au bâton en bas. Faites de nombreux copeaux fins — 20 ou plus par bâton.</p><p>4. Les copeaux devraient s'enrouler vers l'extérieur comme des plumes. Plus les boucles sont fines et nombreuses, plus elles attraperont une étincelle facilement.</p><p>5. Faites plusieurs bâtons à plumes. Le premier attrape l'étincelle, et les bâtons supplémentaires fournissent progressivement plus de combustible à mesure que le feu grandit.</p><p>Les bâtons à plumes sont une compétence de survie critique car les conditions humides sont celles où vous avez le plus besoin d'un feu (pour la chaleur) et où le feu est le plus difficile à allumer. Maîtrisez cette technique et vous pourrez allumer un feu dans presque toutes les conditions.</p>"""

with open('fr_long_articles.json', 'w', encoding='utf-8') as f:
    json.dump(translations, f, ensure_ascii=False, indent=2)

print(f"Generated {len(translations)} article translations")
print("Saved to fr_long_articles.json")

# Verify
loaded = json.load(open('fr_long_articles.json'))
print(f"Verified: {len(loaded)} entries loaded successfully")
